  "mandatory": {
    "type": "boolean",
    "title": "Mandatory",
    "description": "\ud83d\udcaf Whether the connector is mandatory. A mandatory connector must be connected in a design.",
    "default": false
  },
  "maxChildren": {
    "default": 1,
    "description": "The optional maximum number of children (connections) that can be connected.",
    "minimum": 0,
    "title": "Maxchildren",
    "type": "integer"
  },
  "port": {
    "type": "string",
    "maxLength": 64,
    "title": "Port",
    "description": "\ud83d\udc68\u200d\ud83d\udc69\u200d\ud83d\udc67\u200d\ud83d\udc66 The optional port of the connector. This allows to define explicit compatibility with other connectors.",
    "default": ""
  },
  "compatiblePorts": {
    "items": {
      "type": "string"
    },
    "type": "array",
    "title": "Compatibleports",
    "description": "\u2705 The optional other compatible ports of the connector. An empty list means this connector is compatible with all other connectors."
  },
  "point": {
    "$ref": "#/components/schemas/Point",
    "description": "\u2716\ufe0f The connection point of the connector that is attracted to another connection point."
  },
  "direction": {
    "$ref": "#/components/schemas/Vector",
    "description": "\u27a1\ufe0f The direction of the connector. When another piece connects the direction of the other connector is flipped and then the pieces are aligned."
  },
  "t": {
    "type": "number",
    "title": "T",
    "description": "\ud83d\udc8d The parameter t [0,1[ where the connector will be shown on the ring of a piece in the diagram. It starts at 12 o`clock and turns clockwise.",
    "default": 0.0
  },
  "attributes": {
    "items": {
      "$ref": "#/components/schemas/AttributeContext"
    },
    "type": "array",
    "title": "Attributes",
    "description": "\ud83d\udccf The attributes of the connector."
  }
},
"type": "object",
"required": [
  "point",
  "direction"
],
"title": "ConnectorContext",

